import test from 'node:test';
import assert from 'node:assert/strict';
import { compileFilter } from '../src/queryDsl.mjs';
import { BatchIngestor } from '../src/batchIngestor.mjs';

test('T08 visible: escaped trailing backslash and AND-over-OR precedence', () => {
  const pathPred = compileFilter('path == "C:\\\\temp\\\\"');
  assert.equal(pathPred({ path: 'C:\\temp\\' }), true);
  assert.equal(pathPred({ path: 'C:\\other\\' }), false);

  // AND binds tighter than OR: a == 1 OR (b == 2 AND c == 3)
  const precPred = compileFilter('a == 1 OR b == 2 AND c == 3');
  assert.equal(precPred({ a: 1, b: 0, c: 0 }), true);
  assert.equal(precPred({ a: 0, b: 2, c: 0 }), false);
});

test('T08 visible: BatchIngestor preserves events when sink rejects', async () => {
  let failOnce = true;
  const delivered = [];
  const ingestor = new BatchIngestor({
    maxBatchSize: 10,
    sinkFn: async (batch) => {
      if (failOnce) {
        failOnce = false;
        throw new Error('transient sink error');
      }
      delivered.push(...batch);
    }
  });
  await ingestor.ingest({ seq: 1, metric: 'm', units: 5 });
  await ingestor.ingest({ seq: 2, metric: 'm', units: 6 });

  await assert.rejects(() => ingestor.flush(), /transient sink error/);
  assert.equal(ingestor.pendingCount, 2);
  assert.equal(ingestor.committedWatermarkSeq, 0);

  await ingestor.flush();
  assert.equal(ingestor.pendingCount, 0);
  assert.equal(ingestor.committedWatermarkSeq, 2);
  assert.deepEqual(delivered.map((x) => x.seq), [1, 2]);
});
import { ERROR_CODES, LedgerError } from './errors.mjs';

/**
 * Tokenizes a filter expression into typed tokens.
 *
 * @param {string} expr
 * @returns {Array<{ type: string, value: any }>}
 */
export function tokenizeDsl(expr) {
  if (typeof expr !== 'string' || !expr.trim()) {
    throw new LedgerError(ERROR_CODES.ERR_DSL_SYNTAX, 'Filter expression must be a non-empty string');
  }
  const tokens = [];
  let i = 0;
  while (i < expr.length) {
    const ch = expr[i];
    if (/\s/.test(ch)) {
      i += 1;
      continue;
    }
    if (ch === '(' || ch === ')' || ch === ',') {
      tokens.push({ type: ch, value: ch });
      i += 1;
      continue;
    }
    if (ch === '"') {
      let j = i + 1;
      let buf = '';
      while (j < expr.length) {
        if (expr[j] === '"' && expr[j - 1] !== '\\') break;
        buf += expr[j];
        j += 1;
      }
      if (j >= expr.length) {
        throw new LedgerError(ERROR_CODES.ERR_DSL_SYNTAX, 'Unterminated string literal');
      }
      tokens.push({ type: 'STRING', value: buf });
      i = j + 1;
      continue;
    }
    const two = expr.slice(i, i + 2);
    if (two === '==' || two === '!=' || two === '>=' || two === '<=') {
      tokens.push({ type: 'OP', value: two });
      i += 2;
      continue;
    }
    if (ch === '>' || ch === '<') {
      tokens.push({ type: 'OP', value: ch });
      i += 1;
      continue;
    }
    if (/[0-9-]/.test(ch)) {
      const m = /^-?\d+(?:\.\d+)?/.exec(expr.slice(i));
      if (m) {
        tokens.push({ type: 'NUMBER', value: Number(m[0]) });
        i += m[0].length;
        continue;
      }
    }
    const ident = /^[A-Za-z_][A-Za-z0-9_.]*/.exec(expr.slice(i));
    if (ident) {
      const word = ident[0];
      const upper = word.toUpperCase();
      if (upper === 'AND' || upper === 'OR' || upper === 'NOT') {
        tokens.push({ type: upper, value: upper });
      } else if (upper === 'TRUE' || upper === 'FALSE') {
        tokens.push({ type: 'BOOLEAN', value: upper === 'TRUE' });
      } else if (upper === 'NULL') {
        tokens.push({ type: 'NULL', value: null });
      } else {
        tokens.push({ type: 'IDENT', value: word });
      }
      i += word.length;
      continue;
    }
    throw new LedgerError(ERROR_CODES.ERR_DSL_SYNTAX, `Unexpected character: ${ch}`);
  }
