import { ERROR_CODES, LedgerError } from './errors.mjs';

/** Supported escape sequences inside string literals (char after the backslash -> decoded value). */
const STRING_ESCAPES = Object.freeze({
  '\\': '\\',
  '"': '"',
  n: '\n',
  t: '\t'
});

function syntaxError(message) {
  return new LedgerError(ERROR_CODES.ERR_DSL_SYNTAX, message);
}

/**
 * Scans a double-quoted string literal starting at `start` (which must point at the opening quote).
 *
 * @param {string} expr
 * @param {number} start
 * @returns {{ value: string, end: number }} decoded value and index just past the closing quote
 */
function scanStringLiteral(expr, start) {
  let j = start + 1;
  let buf = '';
  while (j < expr.length) {
    const c = expr[j];
    if (c === '"') {
      return { value: buf, end: j + 1 };
    }
    if (c === '\\') {
      if (j + 1 >= expr.length) {
        throw syntaxError('Dangling escape at end of string literal');
      }
      const next = expr[j + 1];
      if (!Object.prototype.hasOwnProperty.call(STRING_ESCAPES, next)) {
        throw syntaxError(`Invalid escape sequence: \\${next}`);
      }
      buf += STRING_ESCAPES[next];
      j += 2;
      continue;
    }
    buf += c;
    j += 1;
  }
  throw syntaxError('Unterminated string literal');
}

/**
 * Tokenizes a filter expression into typed tokens.
 *
 * @param {string} expr
 * @returns {Array<{ type: string, value: any }>}
 */
export function tokenizeDsl(expr) {
  if (typeof expr !== 'string' || !expr.trim()) {
    throw syntaxError('Filter expression must be a non-empty string');
  }
  const tokens = [];
  let i = 0;
  while (i < expr.length) {
    const ch = expr[i];
    if (/\s/.test(ch)) {
      i += 1;
      continue;
    }
    if (ch === '(' || ch === ')' || ch === ',') {
      tokens.push({ type: ch, value: ch });
      i += 1;
      continue;
    }
    if (ch === '"') {
      const { value, end } = scanStringLiteral(expr, i);
      tokens.push({ type: 'STRING', value });
      i = end;
      continue;
    }
    const two = expr.slice(i, i + 2);
    if (two === '==' || two === '!=' || two === '>=' || two === '<=') {
      tokens.push({ type: 'OP', value: two });
      i += 2;
      continue;
    }
    if (ch === '>' || ch === '<') {
      tokens.push({ type: 'OP', value: ch });
      i += 1;
      continue;
    }
    if (/[0-9-]/.test(ch)) {
      const m = /^-?\d+(?:\.\d+)?/.exec(expr.slice(i));
      if (m) {
        tokens.push({ type: 'NUMBER', value: Number(m[0]) });
        i += m[0].length;
        continue;
      }
    }
    const ident = /^[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z0-9_]+)*/.exec(expr.slice(i));
    if (ident) {
      const word = ident[0];
      if (expr[i + word.length] === '.') {
        throw syntaxError(`Malformed field path: ${word}.`);
      }
      const upper = word.toUpperCase();
      if (upper === 'AND' || upper === 'OR' || upper === 'NOT') {
        tokens.push({ type: upper, value: upper });
      } else if (upper === 'TRUE' || upper === 'FALSE') {
        tokens.push({ type: 'BOOLEAN', value: upper === 'TRUE' });
      } else if (upper === 'NULL') {
        tokens.push({ type: 'NULL', value: null });
      } else {
        tokens.push({ type: 'IDENT', value: word });
      }
      i += word.length;
      continue;
    }
    throw syntaxError(`Unexpected character: ${ch}`);
  }
  return tokens;
}

/**
 * Resolves a dotted path against an object. Any missing segment yields `undefined`.
 * Only own properties are followed (inherited members such as `toString` count as missing).
 */
function resolveField(obj, pathStr) {
  const parts = String(pathStr).split('.');
  let cur = obj;
  for (const part of parts) {
    if (cur === null || cur === undefined || typeof cur !== 'object') return undefined;
    if (!Object.prototype.hasOwnProperty.call(cur, part)) return undefined;
    cur = cur[part];
  }
  return cur;
}

function isNullish(v) {
  return v === null || v === undefined;
}

function isUncomparable(v) {
  return isNullish(v) || (typeof v === 'number' && Number.isNaN(v));
}

function looseNullEquals(a, b) {
  if (isNullish(a) || isNullish(b)) return isNullish(a) && isNullish(b);
  return a === b;
}

function orderedCompare(op, a, b) {
  if (isUncomparable(a) || isUncomparable(b)) return false;
  const t = typeof a;
  if (t !== typeof b || (t !== 'number' && t !== 'string')) return false;
  switch (op) {
    case '>': return a > b;
    case '>=': return a >= b;
    case '<': return a < b;
    case '<=': return a <= b;
    default: return false;
  }
}

/**
 * Compiles a filter expression string into `(event) => boolean`.
 *
 * Grammar (strict precedence: `()` > `NOT` > `AND` > `OR`):
 *   orExpr  := andExpr ( OR andExpr )*
 *   andExpr := notExpr ( AND notExpr )*
 *   notExpr := NOT notExpr | primary
 *   primary := '(' orExpr ')' | IDENT OP literal
 *
 * @param {string} expr
 * @returns {(event: object) => boolean}
 */
export function compileFilter(expr) {
  const tokens = tokenizeDsl(expr);
  let pos = 0;

  function peek() {
    return tokens[pos] || null;
  }

  function consume(expectedType = null) {
    const tok = tokens[pos];
    if (!tok || (expectedType && tok.type !== expectedType)) {
      throw syntaxError(`Expected ${expectedType || 'token'}, got ${tok ? tok.type : 'EOF'}`);
    }
    pos += 1;
    return tok;
  }

  function parseOr() {
    let left = parseAnd();
    while (peek() && peek().type === 'OR') {
      consume('OR');
      const right = parseAnd();
      const prevLeft = left;
      left = (evt) => prevLeft(evt) || right(evt);
    }
    return left;
  }

  function parseAnd() {
    let left = parseNot();
    while (peek() && peek().type === 'AND') {
      consume('AND');
      const right = parseNot();
      const prevLeft = left;
      left = (evt) => prevLeft(evt) && right(evt);
    }
    return left;
  }

  function parseNot() {
    if (peek() && peek().type === 'NOT') {
      consume('NOT');
      const inner = parseNot();
      return (evt) => !inner(evt);
    }
    return parsePrimary();
  }

  function parsePrimary() {
    const tok = peek();
    if (!tok) throw syntaxError('Unexpected end of filter');
    if (tok.type === '(') {
      consume('(');
      const inner = parseOr();
      consume(')');
      return inner;
    }
    const fieldTok = consume('IDENT');
    const opTok = consume('OP');
    const valTok = consume();
    if (!['STRING', 'NUMBER', 'BOOLEAN', 'NULL'].includes(valTok.type)) {
      throw syntaxError(`Unexpected literal token: ${valTok.type}`);
    }
    const field = fieldTok.value;
    const op = opTok.value;
    const target = valTok.value;
    return (evt) => {
      const actual = resolveField(evt, field);
      switch (op) {
        case '==': return looseNullEquals(actual, target);
        case '!=': return !looseNullEquals(actual, target);
        default: return orderedCompare(op, actual, target);
      }
    };
  }

  const fn = parseOr();
  if (pos !== tokens.length) {
    throw syntaxError(`Unexpected trailing token ${tokens[pos].value}`);
  }
  return (evt) => Boolean(fn(evt));
}

