import { ERROR_CODES, LedgerError } from './errors.mjs';

/** Supported escape sequences inside string literals (char after the backslash -> decoded value). */
const STRING_ESCAPES = Object.freeze({
  '\\': '\\',
  '"': '"',
  n: '\n',
  t: '\t'
});

function syntaxError(message) {
  return new LedgerError(ERROR_CODES.ERR_DSL_SYNTAX, message);
}

