cd "<REPO_DIR>" && npm test 2>&1 | tail -12; mkdir -p ../scratch && cat > ../scratch/check.mjs <<'EOF'
import { compileFilter } from '../repo/src/queryDsl.mjs';
import { BatchIngestor } from '../repo/src/batchIngestor.mjs';
const ok = (c, m) => { if (!c) { console.log('FAIL', m); process.exitCode = 1; } };
const throwsDsl = (e) => { try { compileFilter(e); return false; } catch (x) { return x.code === 'ERR_DSL_SYNTAX'; } };
ok(compileFilter(String.raw`s == "a\"b\n\t\\"`)({ s: 'a"b\n\t\\' }), 'escapes');
ok(throwsDsl(String.raw`p == "x\`), 'dangling');
ok(throwsDsl('p == "x'), 'unterminated');
ok(throwsDsl(String.raw`p == "\q"`), 'bad escape');
ok(throwsDsl('a == 1 AND'), 'dangling AND');
ok(throwsDsl('(a == 1'), 'missing paren');
ok(throwsDsl('a. == 1'), 'bad path');
ok(compileFilter('NOT a == 1 AND b == 2')({ a: 0, b: 0 }) === false, 'NOT>AND');
ok(compileFilter('NOT a == 1 AND b == 2')({ a: 0, b: 2 }) === true, 'NOT>AND 2');
ok(compileFilter('a == 1 AND b == 2 OR c == 3')({ a: 0, b: 0, c: 3 }) === true, 'AND>OR');
ok(compileFilter('NOT (a == 1 OR b == 2)')({ a: 0, b: 0 }) === true, 'parens');
ok(compileFilter('NOT NOT a == 1')({ a: 1 }) === true, 'double NOT');
ok(compileFilter('x.y == null')({}) === true, 'missing==null');
ok(compileFilter('x.y == null')({ x: { y: null } }) === true, 'null==null');
ok(compileFilter('x != "q"')({}) === true, 'missing!=x');
ok(compileFilter('x != null')({}) === false, 'missing!=null');
ok(compileFilter('x == "q"')({ x: null }) === false, 'null==q');
for (const op of ['<', '<=', '>', '>=']) {
  ok(compileFilter(`x ${op} 5`)({}) === false, 'missing ' + op);
  ok(compileFilter(`x ${op} 5`)({ x: null }) === false, 'null ' + op);
  ok(compileFilter(`x ${op} 5`)({ x: NaN }) === false, 'NaN ' + op);
  ok(compileFilter(`x ${op} null`)({ x: 3 }) === false, 'lit null ' + op);
}
ok(compileFilter('x >= 5')({ x: 5 }) === true, 'gte');
ok(compileFilter('toString == null')({}) === true, 'proto');

// concurrency
let active = 0, maxActive = 0; const got = [];
const ing = new BatchIngestor({ maxBatchSize: 2, sinkFn: async (b) => { active++; maxActive = Math.max(maxActive, active); await new Promise(r => setTimeout(r, 5)); got.push(...b.map(x => x.seq)); active--; } });
await Promise.all([1,2,3,4,5,6,7].map(s => ing.ingest({ seq: s, metric: 'm', units: 1 })).concat([ing.flush()]));
await ing.flush();
ok(maxActive === 1, 'maxActive ' + maxActive);
ok(JSON.stringify(got) === '[1,2,3,4,5,6,7]', 'order ' + got);
ok(ing.totalCommitted === 7 && ing.committedWatermarkSeq === 7, 'counters');

// rollback with mid-flight ingest
let fail = true; const del = [];
const ing2 = new BatchIngestor({ maxBatchSize: 100, sinkFn: async (b) => { await new Promise(r => setTimeout(r, 5)); if (fail) { fail = false; throw new Error('boom'); } del.push(...b.map(x => x.seq)); } });
await ing2.ingest({ seq: 1, metric: 'm' }); await ing2.ingest({ seq: 2, metric: 'm' });
const p = ing2.flush();
await ing2.ingest({ seq: 3, metric: 'm' });
await p.then(() => ok(false, 'should reject'), (e) => ok(e.message === 'boom', 'msg'));
ok(ing2.pendingCount === 3 && ing2.committedWatermarkSeq === 0 && ing2.totalCommitted === 0, 'rollback state');
await ing2.flush();
ok(JSON.stringify(del) === '[1,2,3]', 'retry order ' + del);
console.log('checks done');
EOF
node ../scratch/check.mjs; grep -rnE "eval\(|new Function" src; git status --short

